1	//! iOS Keychain storage for identity-wallet credentials.
2	//!
3	//! All items are stored as `kSecClassGenericPassword` under
4	//! service `"ezpds-identity-wallet"`. Use the `SERVICE` constant
5	//! to ensure consistency.
6	//!
7	//! # Two stores, not one attribute
8	//!
9	//! The module exposes two families of accessors. `store_item`/`get_item`/`delete_item`
10	//! address the **device-local** store: those items reach a second device by no route the
11	//! wallet uses (iCloud Backup re-encrypts the keychain to the device UID and restores only
12	//! to the same device). `store_item_synced`/`get_item_synced`/`delete_item_synced` address
13	//! the **iCloud-synchronizable** store by setting `kSecAttrSynchronizable`.
14	//!
15	//! These are genuinely different stores, not one item with a flag: Apple's `SecItem.h` is
16	//! explicit that an item is identified by its service + account **and** its synchronizable
17	//! option, and that "if the key is not supplied … no synchronizable items will be added or
18	//! returned." A value written with `store_item` is therefore invisible to `get_item_synced`
19	//! and vice versa. Nothing in `SecItem.h` documents changing an existing item's
20	//! synchronizability, so moving a value between the stores means copying it, never flipping
21	//! it in place.
22	//!
23	//! Accessibility is left at the framework default (`kSecAttrAccessibleWhenUnlocked`) for
24	//! synchronizable items — the `…ThisDeviceOnly` accessibility classes are mutually exclusive
25	//! with syncing.
26	//!
27	//! # Which access group items land in
28	//!
29	//! An item's address has a third dimension beyond service + account: the **access group**.
30	//! With no `keychain-access-groups` entitlement it defaults to the implicit
31	//! `$(AppIdentifierPrefix)<bundle-id>` group — i.e. the access group *is* the bundle id,
32	//! and renaming the bundle makes every stored item invisible with no error and no recovery
33	//! path short of the share ceremony.
34	//!
35	//! `Entitlements.ios.plist` therefore declares the group explicitly, and the array order is
36	//! the mechanism: iOS files an item into the **first** entitled group when a write does not
37	//! name one, and searches **every** entitled group when a read does not name one. Because no
38	//! accessor here sets `kSecAttrAccessGroup`, writes land in [`STABLE_ACCESS_GROUP`] and reads
39	//! span stable-then-legacy for free. That is deliberate — resolving the literal group string
40	//! in Rust would mean discovering the team's `AppIdentifierPrefix` at runtime, adding a
41	//! failure mode to every Keychain call to re-implement what the OS already guarantees.
42	//!
43	//! The invariant that *is* worth enforcing is the entitlement's shape, which no call site can
44	//! observe; `entitlement_declares_stable_group_first` asserts it against the tracked plist at
45	//! compile time, and `just bundle-identity-check` re-asserts it alongside the bundle id and
46	//! the iCloud container. See ADR-0030.
47	//!
48	//! In test builds (`#[cfg(test)]`), all Keychain operations are redirected to an
49	//! in-memory store so that tests never touch the real macOS Keychain and never
50	//! trigger a password prompt. The test store models the two-store split faithfully —
51	//! the same account in the synced and device-local namespaces is two independent values.
52	
53	#[cfg(not(test))]
54	use security_framework::passwords::{
55	    delete_generic_password, delete_generic_password_options, generic_password,
56	    get_generic_password, set_generic_password, set_generic_password_options, PasswordOptions,
57	};
58	
59	pub const SERVICE: &str = "ezpds-identity-wallet";
60	
61	/// The Keychain access group every new item is written to, minus the team's
62	/// `$(AppIdentifierPrefix)`.
63	///
64	/// Deliberately not derived from the bundle id, so a `dev.malpercio.*` → `org.obsign.*`
65	/// rename cannot move it. Must stay **first** in `Entitlements.ios.plist`'s
66	/// `keychain-access-groups` array — that position is what makes it the write target.
67	pub const STABLE_ACCESS_GROUP: &str = "org.obsign.shared";
68	
69	/// The group items were written to before [`STABLE_ACCESS_GROUP`] existed: the implicit
70	/// `$(AppIdentifierPrefix)<bundle-id>` group of the original `dev.malpercio.identitywallet`
71	/// bundle.
72	///
73	/// Pinned as a literal rather than read from `tauri.conf.json`'s current identifier —
74	/// deriving it would let a rename quietly redefine "legacy" to the new bundle id and orphan
75	/// exactly the items this exists to keep reachable. It must remain declared for as long as
76	/// any install may still hold items there, which is indefinitely: an install that never
77	/// updates never migrates.
78	pub const LEGACY_ACCESS_GROUP: &str = "dev.malpercio.identitywallet";
79	
80	#[derive(Debug, thiserror::Error)]
81	pub enum KeychainError {
82	    #[error("keychain error: {0}")]
83	    Security(#[from] security_framework::base::Error),
84	    /// A synchronizable-store accessor was called for an account that is not on the
85	    /// iCloud allowlist. Never reachable from the shipped call sites — the guard exists so
86	    /// a future caller cannot quietly widen what leaves the device.
87	    #[error("account {account} is not permitted in the iCloud-synchronizable keychain")]
88	    SyncNotPermitted { account: String },
89	    /// Returned by the in-memory test store when an item is not found.
90	    #[cfg(test)]
91	    #[error("item not found")]
92	    NotFound,
93	}
94	
95	/// Whether `account` is permitted in the **iCloud-synchronizable** Keychain store.
96	///
97	/// A deliberate allowlist of exactly one account family — the per-DID Shamir Share 1 slot
98	/// `recovery-share-1:{did}` — because Share 1 is the only wallet secret whose entire job is
99	/// to survive the loss of the device that created it. Everything else the wallet holds is
100	/// device-local by design, and each exclusion is load-bearing rather than incidental:
101	///
102	/// * **the device key** (`device-rotation-key-*`, `{did}:device-key*`) — on a real device it
103	///   is a Secure Enclave key that *cannot* leave the hardware, and the software fallback must
104	///   not be more portable than the thing it stands in for. It is `rotationKeys[0]`: one
105	///   device, one key, is what makes the 72-hour PLC override meaningful.
106	/// * **`{did}:oauth-tokens`** — a bearer session for one device. Syncing it would put a live
107	///   credential in the Apple account for no recovery benefit; a recovered wallet mints its
108	///   own via sovereign login.
109	/// * **`{did}:recovery-signing-key`** — the self-controlled `atproto` repo signing key. It
110	///   signs commits, so a second live copy is a fork risk, not a backup.
111	/// * **`ceremony-staging` / `recovery-epilogue`** — in-flight ceremony records whose whole
112	///   contract is fail-closed single-device ownership. Two devices resuming one epilogue is a
113	///   correctness hazard, not a convenience: each would drive the same rotation independently
114	///   against a record it believes it owns. They also hold the *seed* (or two shares at once)
115	///   until teardown, so syncing them would place a reconstructable secret in iCloud,
116	///   collapsing the 2-of-3 threshold this whole design exists to hold.
117	///
118	/// Asserted by `deny_list_accounts_never_sync` below.
119	pub fn syncs_to_icloud(account: &str) -> bool {
120	    crate::rekey::is_recovery_share1_account(account)
121	}
122	
123	/// Reject a synchronizable-store call for a non-allowlisted account.
124	fn guard_sync_allowed(account: &str) -> Result<(), KeychainError> {
125	    if syncs_to_icloud(account) {
126	        Ok(())
127	    } else {
128	        Err(KeychainError::SyncNotPermitted {
129	            account: account.to_string(),
130	        })
131	    }
132	}
133	
134	/// Store bytes in the **iCloud-synchronizable** Keychain store.
135	///
136	/// Writes a record distinct from any same-named `store_item` record; it does not migrate,
137	/// replace, or delete the device-local one. Only allowlisted accounts (see
138	/// [`syncs_to_icloud`]) are accepted.
139	///
140	/// A successful return means the item was written carrying `kSecAttrSynchronizable` — **not**
141	/// that it reached the user's Apple account. iOS exposes no delivery callback, and with
142	/// iCloud Keychain switched off the attribute is recorded and propagates nowhere (enabling it
143	/// later syncs the item with no further involvement from this app). User-facing copy must
144	/// claim only the former.
145	pub fn store_item_synced(account: &str, data: &[u8]) -> Result<(), KeychainError> {
146	    guard_sync_allowed(account)?;
147	    #[cfg(test)]
148	    {
149	        test_store::set(test_store::Scope::Synced, account, data.to_vec());
150	        Ok(())
151	    }
152	    #[cfg(not(test))]
153	    set_generic_password_options(data, synced_options(account)).map_err(KeychainError::Security)
154	}
155	
156	/// Retrieve bytes from the **iCloud-synchronizable** Keychain store.
157	///
158	/// Returns `Err` with `errSecItemNotFound` when the synced slot is empty, even if a
159	/// device-local item with the same account exists.
160	pub fn get_item_synced(account: &str) -> Result<Vec<u8>, KeychainError> {
161	    guard_sync_allowed(account)?;
162	    #[cfg(test)]
163	    {
164	        test_store::get(test_store::Scope::Synced, account).ok_or(KeychainError::NotFound)
165	    }
166	    #[cfg(not(test))]
167	    generic_password(synced_options(account)).map_err(KeychainError::Security)
168	}
169	
170	/// Delete an item from the **iCloud-synchronizable** Keychain store, leaving any
171	/// device-local item of the same name untouched.
172	#[cfg_attr(test, allow(dead_code))]
173	pub fn delete_item_synced(account: &str) -> Result<(), KeychainError> {
174	    guard_sync_allowed(account)?;
175	    #[cfg(test)]
176	    {
177	        test_store::delete(test_store::Scope::Synced, account);
178	        Ok(())
179	    }
180	    #[cfg(not(test))]
181	    delete_generic_password_options(synced_options(account)).map_err(KeychainError::Security)
182	}
183	
184	/// Query targeting the synchronizable store for `account`.
185	///
186	/// `Some(true)` (never `None`) so every operation addresses exactly one store: with `None`,
187	/// a set would prefer the device-local store and a get could not say which store answered.
188	#[cfg(not(test))]
189	fn synced_options(account: &str) -> PasswordOptions {
190	    let mut options = PasswordOptions::new_generic_password(SERVICE, account);
191	    options.set_access_synchronized(Some(true));
192	    options
193	}
194	
195	/// Store arbitrary bytes in the **device-local** Keychain store under the given account name.
196	///
197	/// Creates the entry if it doesn't exist, or updates it if it does. The value stays on this
198	/// device; see [`store_item_synced`] for the iCloud-synchronizable store.
199	pub fn store_item(account: &str, data: &[u8]) -> Result<(), KeychainError> {
200	    #[cfg(test)]
201	    {
202	        test_store::set(test_store::Scope::Local, account, data.to_vec());
203	        Ok(())
204	    }
205	    #[cfg(not(test))]
206	    set_generic_password(SERVICE, account, data).map_err(KeychainError::Security)
207	}
208	
209	/// Retrieve bytes from the **device-local** Keychain store for the given account name.
210	///
211	/// Returns `Err` with `errSecItemNotFound` if no entry exists. Never returns a value written
212	/// by [`store_item_synced`].
213	pub fn get_item(account: &str) -> Result<Vec<u8>, KeychainError> {
214	    #[cfg(test)]
215	    {
216	        test_store::get(test_store::Scope::Local, account).ok_or(KeychainError::NotFound)
217	    }
218	    #[cfg(not(test))]
219	    get_generic_password(SERVICE, account).map_err(KeychainError::Security)
220	}
221	
222	/// Delete an item from the **device-local** Keychain store by account name.
223	///
224	/// Returns `Ok(())` on successful deletion, or `Err` if the item doesn't exist.
225	pub fn delete_item(account: &str) -> Result<(), KeychainError> {
226	    #[cfg(test)]
227	    {
228	        test_store::delete(test_store::Scope::Local, account);
229	        Ok(())
230	    }
231	    #[cfg(not(test))]
232	    delete_generic_password(SERVICE, account).map_err(KeychainError::Security)
233	}
234	
235	/// `errSecItemNotFound` — the Security framework's "no such item" status.
236	///
237	/// Callers that hold a raw `security_framework` error rather than a `KeychainError`
238	/// (a direct `ItemSearchOptions` query, for instance) compare against this instead of
239	/// re-spelling the magic number.
240	pub const ERR_SEC_ITEM_NOT_FOUND: i32 = -25300;
241	
242	/// Returns true if the error is errSecItemNotFound (OS status -25300).
243	/// Use this to distinguish "item does not exist" from transient OS errors.
244	pub fn is_not_found(err: &KeychainError) -> bool {
245	    match err {
246	        KeychainError::Security(e) => e.code() == ERR_SEC_ITEM_NOT_FOUND,
247	        // Not an absence claim — the account was never addressed.
248	        KeychainError::SyncNotPermitted { .. } => false,
249	        #[cfg(test)]
250	        KeychainError::NotFound => true,
251	    }
252	}
253	
254	// ── OAuth Keychain helpers ─────────────────────────────────────────────────────
255	
256	const DPOP_KEY_PRIV_ACCOUNT: &str = "oauth-dpop-key-priv";
257	const OAUTH_ACCESS_TOKEN_ACCOUNT: &str = "oauth-access-token";
258	const OAUTH_REFRESH_TOKEN_ACCOUNT: &str = "oauth-refresh-token";
259	const PDS_URL_ACCOUNT: &str = "relay-base-url";
260	const APPEARANCE_ACCOUNT: &str = "appearance-preference";
261	
262	/// Store the DPoP private key scalar (32 bytes) in the Keychain.
263	pub fn store_dpop_key(private_bytes: &[u8]) -> Result<(), KeychainError> {
264	    store_item(DPOP_KEY_PRIV_ACCOUNT, private_bytes)
265	}
266	
267	/// Load the DPoP private key scalar from the Keychain.
268	///
269	/// Returns `None` if no key has been stored yet (first run).
270	/// The returned bytes are wrapped in `Zeroizing` to ensure they are cleared on drop.
271	pub fn load_dpop_key() -> Option<zeroize::Zeroizing<[u8; 32]>> {
272	    match get_item(DPOP_KEY_PRIV_ACCOUNT) {
273	        Ok(bytes) if bytes.len() == 32 => {
274	            let mut arr = [0u8; 32];
275	            arr.copy_from_slice(&bytes);
276	            Some(zeroize::Zeroizing::new(arr))
277	        }
278	        Ok(_) => {
279	            tracing::warn!("DPoP key in Keychain has unexpected length; treating as absent");
280	            None
281	        }
282	        Err(e) if is_not_found(&e) => None,
283	        Err(e) => {
284	            tracing::error!(error = ?e, "Keychain error loading DPoP key");
285	            None
286	        }
287	    }
288	}
289	
290	/// Store the OAuth access token and refresh token in the Keychain.
291	pub fn store_oauth_tokens(access_token: &str, refresh_token: &str) -> Result<(), KeychainError> {
292	    store_item(OAUTH_ACCESS_TOKEN_ACCOUNT, access_token.as_bytes())?;
293	    store_item(OAUTH_REFRESH_TOKEN_ACCOUNT, refresh_token.as_bytes())?;
294	    Ok(())
295	}
296	
297	/// Load the OAuth access token and refresh token from the Keychain.
298	///
299	/// Returns `None` if either token is missing (not yet authenticated).
300	pub fn load_oauth_tokens() -> Option<(String, String)> {
301	    let access = match get_item(OAUTH_ACCESS_TOKEN_ACCOUNT) {
302	        Ok(b) => match String::from_utf8(b) {
303	            Ok(s) => s,
304	            Err(e) => {
305	                tracing::error!(error = ?e, "UTF-8 error decoding access token from Keychain");
306	                return None;
307	            }
308	        },
309	        Err(e) if is_not_found(&e) => return None,
310	        Err(e) => {
311	            tracing::error!(error = ?e, "Keychain error loading access token");
312	            return None;
313	        }
314	    };
315	    let refresh = match get_item(OAUTH_REFRESH_TOKEN_ACCOUNT) {
316	        Ok(b) => match String::from_utf8(b) {
317	            Ok(s) => s,
318	            Err(e) => {
319	                tracing::error!(error = ?e, "UTF-8 error decoding refresh token from Keychain");
320	                return None;
321	            }
322	        },
323	        Err(e) if is_not_found(&e) => return None,
324	        Err(e) => {
325	            tracing::error!(error = ?e, "Keychain error loading refresh token");
326	            return None;
327	        }
328	    };
329	    Some((access, refresh))
330	}
331	
332	/// Persist the user-configured PDS base URL to the Keychain.
333	///
334	/// Overwrites any previously stored URL.
335	pub fn store_pds_url(url: &str) -> Result<(), KeychainError> {
336	    store_item(PDS_URL_ACCOUNT, url.as_bytes())
337	}
338	
339	/// Retrieve the user-configured PDS base URL from the Keychain.
340	///
341	/// Returns `None` if no URL has been saved yet (first run or after logout).
342	pub fn load_pds_url() -> Option<String> {
343	    match get_item(PDS_URL_ACCOUNT) {
344	        Ok(bytes) => String::from_utf8(bytes)
345	            .map_err(|e| {
346	                tracing::error!(error = ?e, "PDS URL in Keychain is not valid UTF-8; treating as absent");
347	            })
348	            .ok(),
349	        Err(e) if is_not_found(&e) => None,
350	        Err(e) => {
351	            tracing::error!(error = ?e, "Keychain error loading PDS URL");
352	            None
353	        }
354	    }
355	}
356	
357	/// Remove the PDS URL from the Keychain. Test-only; used to reset state
358	/// between tests that share the Keychain mock store.
359	#[cfg(test)]
360	pub fn delete_pds_url_test_only() {
361	    let _ = delete_item(PDS_URL_ACCOUNT);
362	}
363	
364	/// Persist the in-app appearance preference (`"system"`, `"light"`, or `"dark"`).
365	///
366	/// The Keychain is the durable source of truth; the frontend keeps a
367	/// localStorage mirror purely so the preference can apply before first paint
368	/// (an async IPC read would land after the WebView has already painted).
369	pub fn store_appearance_preference(preference: &str) -> Result<(), KeychainError> {
370	    store_item(APPEARANCE_ACCOUNT, preference.as_bytes())
371	}
372	
373	/// Retrieve the stored appearance preference.
374	///
375	/// Returns `None` if no preference has been saved yet (follow the system).
376	pub fn load_appearance_preference() -> Option<String> {
377	    match get_item(APPEARANCE_ACCOUNT) {
378	        Ok(bytes) => String::from_utf8(bytes)
379	            .map_err(|e| {
380	                tracing::error!(error = ?e, "appearance preference in Keychain is not valid UTF-8; treating as absent");
381	            })
382	            .ok(),
383	        Err(e) if is_not_found(&e) => None,
384	        Err(e) => {
385	            tracing::error!(error = ?e, "Keychain error loading appearance preference");
386	            None
387	        }
388	    }
389	}
390	
391	/// Remove the appearance preference from the Keychain. Test-only; used to
392	/// reset state between tests that share the Keychain mock store.
393	#[cfg(test)]
394	pub fn delete_appearance_preference_test_only() {
395	    let _ = delete_item(APPEARANCE_ACCOUNT);
396	}
397	
398	/// Reset the in-memory Keychain to a clean state.
399	///
400	/// Call this at the start of every test that touches the Keychain so that
401	/// sequential tests sharing the same OS thread start with an empty store.
402	#[cfg(test)]
403	pub fn clear_for_test() {
404	    test_store::clear_all();
405	}
406	
407	/// In-memory Keychain substitute used exclusively in test builds.
408	///
409	/// Thread-local storage ensures tests on different threads are fully isolated.
410	/// Call `clear_for_test()` at the start of each test to handle sequential
411	/// reuse of the same OS thread by the Rust test harness.
412	///
413	/// Keys are `(scope, account)`, mirroring the real Keychain's two-store split: the same
414	/// account in `Local` and `Synced` is two independent records, and neither accessor family
415	/// can see the other's value. Tests that assert the launch backfill depend on that.
416	#[cfg(test)]
417	mod test_store {
418	    use std::cell::RefCell;
419	    use std::collections::HashMap;
420	
421	    /// Which of the two Keychain stores a call addresses.
422	    #[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
423	    pub enum Scope {
424	        /// The default, device-local store.
425	        Local,
426	        /// The `kSecAttrSynchronizable` (iCloud Keychain) store.
427	        Synced,
428	    }
429	
430	    thread_local! {
431	        static STORE: RefCell<HashMap<(Scope, String), Vec<u8>>> = RefCell::new(HashMap::new());
432	    }
433	
434	    pub fn get(scope: Scope, account: &str) -> Option<Vec<u8>> {
435	        STORE.with(|s| s.borrow().get(&(scope, account.to_string())).cloned())
436	    }
437	
438	    pub fn set(scope: Scope, account: &str, data: Vec<u8>) {
439	        STORE.with(|s| {
440	            s.borrow_mut().insert((scope, account.to_string()), data);
441	        });
442	    }
443	
444	    pub fn delete(scope: Scope, account: &str) {
445	        STORE.with(|s| {
446	            s.borrow_mut().remove(&(scope, account.to_string()));
447	        });
448	    }
449	
450	    pub fn clear_all() {
451	        STORE.with(|s| s.borrow_mut().clear());
452	    }
453	}
454	
455	#[cfg(test)]
456	mod tests {
457	    use super::*;
458	
459	    const DID: &str = "did:plc:REDACTED";
460	
461	    /// The tracked entitlements, embedded at compile time so this assertion cannot drift
462	    /// from the file that actually ships (`ios-postinit`'s Patch H installs this exact
463	    /// content into the generated project).
464	    const ENTITLEMENTS: &str = include_str!("../Entitlements.ios.plist");
465	
466	    /// The `<string>` values of the `keychain-access-groups` array, in declaration order.
467	    fn declared_access_groups() -> Vec<String> {
468	        let after_key = ENTITLEMENTS
469	            .split_once("<key>keychain-access-groups</key>")
470	            .expect("Entitlements.ios.plist declares no keychain-access-groups")
471	            .1;
472	        let array = after_key
473	            .split_once("<array>")
474	            .and_then(|(_, rest)| rest.split_once("</array>"))
475	            .expect("keychain-access-groups is not followed by an <array>")
476	            .0;
477	        array
478	            .split("<string>")
479	            .skip(1)
480	            .map(|entry| {
481	                entry
482	                    .split_once("</string>")
483	                    .expect("unterminated <string> in keychain-access-groups")
484	                    .0
485	                    .trim()
486	                    .to_string()
487	            })
488	            .collect()
489	    }
490	
491	    /// The entitlement's shape is the whole mechanism, and no Rust call site can observe it:
492	    /// the stable group must be FIRST (iOS writes new items to the first entitled group) and
493	    /// the legacy group must still be present (a read that names no group searches every
494	    /// entitled group, which is what keeps pre-rename items reachable). Dropping or
495	    /// reordering either entry orphans live identity material silently.
496	    #[test]
497	    fn entitlement_declares_stable_group_first() {
498	        let groups = declared_access_groups();
499	        assert_eq!(
500	            groups.first().map(String::as_str),
501	            Some(format!("$(AppIdentifierPrefix){STABLE_ACCESS_GROUP}").as_str()),
502	            "the stable group must be first — it is what makes it the write target; got {groups:?}"
503	        );
504	        assert!(
505	            groups.contains(&format!("$(AppIdentifierPrefix){LEGACY_ACCESS_GROUP}")),
506	            "the legacy group must stay declared or pre-rename items become unreachable; got {groups:?}"
507	        );
508	    }
509	
510	    /// The stable group must not track the bundle id — if it did, a rename would move it and
511	    /// the entitlement would be decoration.
512	    #[test]
513	    fn stable_group_is_not_the_bundle_id() {
514	        assert_ne!(STABLE_ACCESS_GROUP, LEGACY_ACCESS_GROUP);
515	        assert!(!ENTITLEMENTS.contains("$(CFBundleIdentifier)"));
516	    }
517	
518	    /// The allowlist admits exactly the per-DID Share 1 slot — not the bare prefix, and not
519	    /// the deprecated app-global `recovery-share-1` account (a pre-unification install's
520	    /// Share 1 is read from there but never written back into iCloud under that name).
521	    #[test]
522	    fn only_per_did_share1_syncs() {
523	        assert!(syncs_to_icloud(&crate::rekey::recovery_share1_account(DID)));
524	        assert!(!syncs_to_icloud("recovery-share-1"));
525	        assert!(!syncs_to_icloud("recovery-share-1:"));
526	    }
527	
528	    /// Every secret the design keeps device-local must stay off the synchronizable store.
529	    /// Adding an account here without a design decision is the failure this guards.
530	    #[test]
531	    fn deny_list_accounts_never_sync() {
532	        let denied = [
533	            // Device key — Secure Enclave on device; `rotationKeys[0]`.
534	            "device-rotation-key-priv",
535	            "device-rotation-key-pub",
536	            "device-rotation-key-app-label",
537	            &format!("{DID}:device-key"),
538	            &format!("{DID}:device-key-pub"),
539	            &format!("{DID}:device-key-app-label"),
540	            // Live per-device credentials and the repo signing key.
541	            &format!("{DID}:oauth-tokens"),
542	            &format!("{DID}:recovery-signing-key"),
543	            // In-flight ceremony records — these hold reconstructable seed material.
544	            crate::share_ceremony::STAGING_ACCOUNT,
545	            crate::share_recovery::EPILOGUE_ACCOUNT,
546	            &format!("rekey-staging:{DID}"),
547	            &format!("self-held-kit-staging:{DID}"),
548	            // The self-held-kit marker: not secret, but nothing outside the Share 1
549	            // family belongs in the synchronizable store.
550	            &crate::self_held_kit::self_held_kit_account(DID),
551	            // Everything else the wallet stores, for completeness.
552	            "oauth-dpop-key-priv",
553	            "oauth-access-token",
554	            "oauth-refresh-token",
555	            "session-token",
556	            "device-token",
557	            "did",
558	            "managed-dids",
559	            "forgotten-dids",
560	            "pending-removals",
561	            "monitor-history",
562	            "relay-base-url",
563	            "appearance-preference",
564	            &format!("{DID}:did-doc"),
565	            &format!("{DID}:plc-log"),
566	        ];
567	        for account in denied {
568	            assert!(
569	                !syncs_to_icloud(account),
570	                "{account} must never be written to the iCloud-synchronizable keychain"
571	            );
572	            assert!(
573	                matches!(
574	                    store_item_synced(account, b"x"),
575	                    Err(KeychainError::SyncNotPermitted { .. })
576	                ),
577	                "{account} must be refused by the synchronizable write path"
578	            );
579	            assert!(matches!(
580	                get_item_synced(account),
581	                Err(KeychainError::SyncNotPermitted { .. })
582	            ));
583	            assert!(matches!(
584	                delete_item_synced(account),
585	                Err(KeychainError::SyncNotPermitted { .. })
586	            ));
587	        }
588	    }
589	
590	    /// A refused sync call is not an "item absent" verdict — a caller must not mistake it
591	    /// for one and conclude the share was never stored.
592	    #[test]
593	    fn sync_not_permitted_is_not_not_found() {
594	        assert!(!is_not_found(&KeychainError::SyncNotPermitted {
595	            account: "device-rotation-key-priv".to_string(),
596	        }));
597	    }
598	
599	    /// The two stores are independent records under one account name — the property the
600	    /// copy-never-flip backfill and the synced-first read path both rest on.
601	    #[test]
602	    fn synced_and_local_slots_are_distinct_records() {
603	        clear_for_test();
604	        let account = crate::rekey::recovery_share1_account(DID);
605	
606	        store_item(&account, b"LEGACY").unwrap();
607	        assert!(get_item_synced(&account).is_err_and(|e| is_not_found(&e)));
608	
609	        store_item_synced(&account, b"SYNCED").unwrap();
610	        assert_eq!(get_item(&account).unwrap(), b"LEGACY");
611	        assert_eq!(get_item_synced(&account).unwrap(), b"SYNCED");
612	
613	        // Deleting one store leaves the other intact.
614	        delete_item_synced(&account).unwrap();
615	        assert_eq!(get_item(&account).unwrap(), b"LEGACY");
616	    }
617	}
