422	    /// One account must not be able to unregister another's device.
423	    #[tokio::test]
424	    async fn unregistering_only_touches_the_callers_own_devices() {
425	        let state = state_with_notifications().await;
426	        seed_account(&state, "did:plc:owner").await;
427	        sqlx::query(
428	            "INSERT INTO accounts (did, email, password_hash, created_at, updated_at) \
429	             VALUES ('did:plc:other', 'other@example.com', 'h', datetime('now'), datetime('now'))",
430	        )
