            // app being opened. Must run before app launch completes — `setup` does. A
            // no-op off-device (scheduling is a device concern; the harness is untouched).
            #[cfg(target_os = "ios")]
            bg_backup::register_and_schedule(app.handle());

            Ok(())
        })
